import * as THREE from 'three';

const CELL_SCALE = 8;

interface ProjectedTriangle {
  ax: number; az: number; ay: number;
  bx: number; bz: number; by: number;
  cx: number; cz: number; cy: number;
  inverse: number;
}
interface SurfaceCell { triangles: ProjectedTriangle[]; low: number; high: number }
interface RearSegment { from: number; to: number; origin: number; height: number; slope: number }

/** The original solid guitar's outer envelope, excluding the intentionally touched strings. */
export class AuthoredGuitarSurface {
  readonly bounds = new THREE.Box3();
  private readonly cells = new Map<number, SurfaceCell>();
  private readonly rearCells = new Map<number, RearSegment[]>();
  private readonly stride: number;
  private readonly minX: number;
  private readonly minZ: number;
  private readonly span = new THREE.Vector2();

  constructor(root: THREE.Group) {
    const guitar = root.getObjectByName('AcousticAcik');
    if (!guitar) throw new Error('The original guitar has no collision surface');
    root.updateMatrixWorld(true);
    const parentInverse = new THREE.Matrix4().copy(root.parent?.matrixWorld ?? new THREE.Matrix4()).invert();
    const triangles: THREE.Vector3[][] = [];
    guitar.traverse(node => {
      if (!(node instanceof THREE.Mesh) || !(node.material instanceof THREE.Material) || node.material.name !== 'APK_acoustic') return;
      const positions = node.geometry.getAttribute('position'), indices = node.geometry.index;
      if (!indices) throw new Error('The original guitar collision surface is not indexed');
      for (let i = 0; i < indices.count; i += 3) {
        const triangle = [0, 1, 2].map(k =>
          new THREE.Vector3().fromBufferAttribute(positions, indices.getX(i + k)).applyMatrix4(node.matrixWorld).applyMatrix4(parentInverse));
        for (const point of triangle) this.bounds.expandByPoint(point);
        triangles.push(triangle);
      }
    });
    if (this.bounds.isEmpty()) throw new Error('The original guitar collision surface is empty');
    this.minX = Math.floor(this.bounds.min.x * CELL_SCALE);
    this.minZ = Math.floor(this.bounds.min.z * CELL_SCALE);
    this.stride = Math.floor(this.bounds.max.z * CELL_SCALE) - this.minZ + 1;
    for (const [a, b, c] of triangles) {
      const denominator = (b.z - c.z) * (a.x - c.x) + (c.x - b.x) * (a.z - c.z);
      if (Math.abs(denominator) < 1e-10) continue;
      const triangle: ProjectedTriangle = {
        ax: a.x, az: a.z, ay: a.y, bx: b.x, bz: b.z, by: b.y, cx: c.x, cz: c.z, cy: c.y,
        inverse: 1 / denominator,
      };
      this.indexRearSegment(triangle);
      for (let x = Math.floor(Math.min(a.x, b.x, c.x) * CELL_SCALE); x <= Math.floor(Math.max(a.x, b.x, c.x) * CELL_SCALE); x++) {
        for (let z = Math.floor(Math.min(a.z, b.z, c.z) * CELL_SCALE); z <= Math.floor(Math.max(a.z, b.z, c.z) * CELL_SCALE); z++) {
          const key = (x - this.minX) * this.stride + z - this.minZ;
          const cell = this.cells.get(key) ?? { triangles: [], low: Infinity, high: -Infinity };
          cell.triangles.push(triangle);
          cell.low = Math.min(cell.low, a.y, b.y, c.y); cell.high = Math.max(cell.high, a.y, b.y, c.y);
          this.cells.set(key, cell);
        }
      }
    }
  }

  private indexRearSegment(p: ProjectedTriangle): void {
    if (Math.floor(Math.min(p.az, p.bz, p.cz) * CELL_SCALE) > 0 || Math.floor(Math.max(p.az, p.bz, p.cz) * CELL_SCALE) < 0) return;
    const uSlope = (p.bz - p.cz) * p.inverse, uZero = (p.cx - p.bx) * -p.cz * p.inverse;
    const vSlope = (p.cz - p.az) * p.inverse, vZero = (p.ax - p.cx) * -p.cz * p.inverse;
    let from = -Infinity, to = Infinity;
    for (const [slope, offset] of [[uSlope, uZero], [vSlope, vZero], [-uSlope - vSlope, 1 - uZero - vZero]]) {
      if (slope > 0) from = Math.max(from, (-1e-8 - offset) / slope);
      else if (slope < 0) to = Math.min(to, (-1e-8 - offset) / slope);
      else if (offset < -1e-8) return;
    }
    if (from > to) return;
    const segment: RearSegment = {
      from: from + p.cx, to: to + p.cx, origin: p.cx,
      height: p.cy + uZero * (p.ay - p.cy) + vZero * (p.by - p.cy),
      slope: uSlope * (p.ay - p.cy) + vSlope * (p.by - p.cy),
    };
    const first = Math.floor(Math.max(segment.from, Math.min(p.ax, p.bx, p.cx)) * CELL_SCALE);
    const last = Math.floor(Math.min(segment.to, Math.max(p.ax, p.bx, p.cx)) * CELL_SCALE);
    for (let x = first; x <= last; x++) {
      const cell = this.rearCells.get(x) ?? [];
      cell.push(segment); this.rearCells.set(x, cell);
    }
  }

  verticalSpan(x: number, z: number, out: THREE.Vector2): boolean {
    if (x < this.bounds.min.x || x > this.bounds.max.x || z < this.bounds.min.z || z > this.bounds.max.z) return false;
    const key = (Math.floor(x * CELL_SCALE) - this.minX) * this.stride + Math.floor(z * CELL_SCALE) - this.minZ;
    let low = Infinity, high = -Infinity;
    for (const p of this.cells.get(key)?.triangles ?? []) {
      const u = ((p.bz - p.cz) * (x - p.cx) + (p.cx - p.bx) * (z - p.cz)) * p.inverse;
      const v = ((p.cz - p.az) * (x - p.cx) + (p.ax - p.cx) * (z - p.cz)) * p.inverse;
      if (u < -1e-8 || v < -1e-8 || u + v > 1 + 1e-8) continue;
      const y = u * p.ay + v * p.by + (1 - u - v) * p.cy;
      low = Math.min(low, y); high = Math.max(high, y);
    }
    out.set(low, high);
    return high - low > 1e-6;
  }

  penetration(point: THREE.Vector3, margin = 0): number {
    if (point.y < this.bounds.min.y - margin || point.y > this.bounds.max.y + margin
      || point.x < this.bounds.min.x || point.x > this.bounds.max.x || point.z < this.bounds.min.z || point.z > this.bounds.max.z) return 0;
    const key = (Math.floor(point.x * CELL_SCALE) - this.minX) * this.stride + Math.floor(point.z * CELL_SCALE) - this.minZ;
    const cell = this.cells.get(key);
    if (!cell || point.y < cell.low - margin || point.y > cell.high + margin) return 0;
    if (!this.verticalSpan(point.x, point.z, this.span)) return 0;
    return Math.max(0, Math.min(this.span.y + margin - point.y, point.y - this.span.x + margin));
  }

  backIntrusion(point: THREE.Vector3, margin = 0): number {
    if (point.y < this.bounds.min.y - margin || !this.verticalSpan(point.x, point.z, this.span)) return 0;
    return Math.max(0, point.y - this.span.x + margin);
  }

  backHeight(x: number): number {
    // Exact triangle/centre-line intersections, not a sampled or quantized neck profile.
    let low = Infinity, high = -Infinity, boundary = false;
    if (x >= this.bounds.min.x && x <= this.bounds.max.x) for (const segment of this.rearCells.get(Math.floor(x * CELL_SCALE)) ?? []) {
      if (Math.abs(x - segment.from) < 2e-8 || Math.abs(x - segment.to) < 2e-8) boundary = true;
      if (x < segment.from || x > segment.to) continue;
      const y = segment.height + (x - segment.origin) * segment.slope;
      low = Math.min(low, y); high = Math.max(high, y);
    }
    if (boundary) {
      if (this.verticalSpan(x, 0, this.span)) return this.span.x;
      low = Infinity; high = -Infinity;
    }
    if (!(high - low > 1e-6)) throw new Error('The original guitar has no rear support surface at this position');
    return low;
  }

  frontIntrusion(point: THREE.Vector3, margin = 0): number {
    if (point.y > this.bounds.max.y + margin || !this.verticalSpan(point.x, point.z, this.span)) return 0;
    return Math.max(0, this.span.y + margin - point.y);
  }
}
