import * as THREE from 'three';
import { suggestFingering } from '../chords/fingering';
import {
  basisRotation, blendPose, chainFK, clonePose, FINGER_CHAIN, CHAIN_NAMES, placeHand, solveChain, toStage,
  type ChainName, type ChainPose, type ChainTarget, type HandKinematics, type HandPose, type PlacementRequest,
} from './handModel';
import type { AuthoredSceneInfo } from './authoredMotion';
import { AuthoredGuitarSurface } from './authoredGuitarSurface';

const X = new THREE.Vector3(1, 0, 0), Y = new THREE.Vector3(0, 1, 0), Z = new THREE.Vector3(0, 0, 1);
// The source joints point along +Z and bend about +X; the shared solver uses -Z and -X.
const AXES = new THREE.Quaternion().setFromAxisAngle(Y, Math.PI);
type Frets = readonly (number | null)[];
interface SkinPoint { local: THREE.Vector3; joint: number; weight: number }
interface SkinBinding { point: THREE.Vector3; influences: { bone: number; weight: number }[] }
interface CollisionSamples { vertices: number[]; faces: number[]; skin: number[] }
const THUMB_LIMITS: [number, number][] = [[-.9, .9], [-.7, 1.4], [-.2, 1.4], [-.12, 1.4]];
// The source Dm7 index distal joint extends to -0.282 radians.
const FINGER_LIMITS: [number, number][] = [[-.65, .65], [-.3, 1.75], [0, 1.95], [-.3, 1.5]];
const THUMB_TWIST: [number, number] = [-1.2, 1.2], FINGER_TWIST: [number, number] = [-.85, .85];
export const AUTHORED_HAND_POSE_VERSION = 4;
export const AUTHORED_THUMB_SUPPORT_LIMIT = .12;

export interface AuthoredHandPoses { version: typeof AUTHORED_HAND_POSE_VERSION; sceneSha256: string; poses: Readonly<Record<string, readonly number[]>> }

export function readAuthoredHandPoses(value: unknown): AuthoredHandPoses {
  if (!value || typeof value !== 'object' || !('version' in value) || value.version !== AUTHORED_HAND_POSE_VERSION
    || !('sceneSha256' in value) || typeof value.sceneSha256 !== 'string' || !/^[0-9a-f]{64}$/.test(value.sceneSha256)
    || !('poses' in value) || !value.poses || typeof value.poses !== 'object' || Array.isArray(value.poses)) {
    throw new Error('Invalid prepared hand catalogue');
  }
  const poses: Record<string, readonly number[]> = {};
  for (const [key, data] of Object.entries(value.poses)) {
    const frets = key.split('.');
    if (frets.length !== 6 || frets.some(fret => fret !== 'x' && (!/^\d+$/.test(fret) || Number(fret) > 20))
      || !Array.isArray(data) || data.length !== 32) throw new Error('Invalid prepared hand pose');
    const packed: number[] = [];
    for (let i = 0; i < 32; i++) {
      const n: unknown = data[i];
      if (typeof n !== 'number' || !Number.isFinite(n)) throw new Error('Invalid prepared hand value');
      if (i >= 7) {
        const joint = (i - 7) % 5;
        const [min, max] = joint === 4 ? i < 12 ? THUMB_TWIST : FINGER_TWIST : (i < 12 ? THUMB_LIMITS : FINGER_LIMITS)[joint];
        if (n < min - 1e-8 || n > max + 1e-8) throw new Error('Prepared hand exceeds native joint limits');
      }
      packed.push(n);
    }
    if (Math.hypot(...packed.slice(0, 3)) > 45 || Math.abs(Math.hypot(...packed.slice(3, 7)) - 1) > .00001) {
      throw new Error('Invalid prepared hand transform');
    }
    poses[key] = Object.freeze(packed);
  }
  if (!Object.keys(poses).length) throw new Error('The prepared hand catalogue is empty');
  return Object.freeze({ version: AUTHORED_HAND_POSE_VERSION, sceneSha256: value.sceneSha256, poses: Object.freeze(poses) });
}

export function packAuthoredHandPose(pose: HandPose): number[] {
  const chains = CHAIN_NAMES.flatMap(name => {
    const chain = pose.chains[name], distal = chain.distal;
    if (distal === undefined || !Number.isFinite(distal)) throw new Error('A prepared native hand needs explicit distal joints');
    const twist = chain.twist ?? 0;
    if (!Number.isFinite(twist)) throw new Error('A prepared native hand needs a finite knuckle rotation');
    return [...chain, distal, twist];
  });
  return [...pose.position.toArray(), ...pose.quaternion.toArray(), ...chains].map(value => Math.round(value * 1e7) / 1e7);
}

function padDistance(joints: THREE.Vector3[], start: THREE.Vector3, end: THREE.Vector3, scale: number): number {
  const line = new THREE.Line3(start, end), point = new THREE.Vector3(), nearest = new THREE.Vector3();
  let error = Infinity;
  for (let k = 0; k < 3; k++) {
    const a = joints[k], delta = joints[k + 1].clone().sub(a);
    const yz = delta.y ** 2 + delta.z ** 2;
    const times = [0, 1, yz ? ((start.y - a.y) * delta.y + (start.z - a.z) * delta.z) / yz : 0,
      start.clone().sub(a).dot(delta) / delta.lengthSq(), end.clone().sub(a).dot(delta) / delta.lengthSq()];
    for (const t of times) {
      const u = THREE.MathUtils.clamp(t, 0, 1);
      point.copy(a).addScaledVector(delta, u);
      const radius = scale * .006 * (k === 2 ? 1 - u : 1);
      const distance = point.distanceTo(line.closestPointToPoint(point, true, nearest));
      error = Math.min(error, Math.abs(distance - radius));
    }
  }
  return error;
}

export interface AuthoredFingerTarget {
  chain: ChainName;
  fret: number;
  strings: number[];
  target: ChainTarget;
}

export function authoredStringPoint(info: AuthoredSceneInfo, string: number, x: number): THREE.Vector3 {
  const { nut, saddle } = info.layout.strings[string];
  const t = (x - nut[0]) / (saddle[0] - nut[0]);
  return new THREE.Vector3(x, nut[1] + t * (saddle[1] - nut[1]), nut[2] + t * (saddle[2] - nut[2]));
}

function stageMatrix(root: THREE.Object3D, node: THREE.Object3D): THREE.Matrix4 {
  const path: THREE.Object3D[] = [];
  for (let current: THREE.Object3D | null = node; current; current = current.parent) {
    path.unshift(current);
    if (current === root) break;
  }
  if (path[0] !== root) throw new Error('An original hand joint is outside its scene');
  const matrix = new THREE.Matrix4();
  for (const object of path) { object.updateMatrix(); matrix.multiply(object.matrix); }
  return matrix;
}

/** Native skeleton adaptation only: source vertices, skin weights, UVs and materials stay untouched. */
export class AuthoredHandRig {
  readonly hand: HandKinematics;
  readonly scale: number;
  private readonly wrist: THREE.Object3D;
  private readonly pivot: THREE.Object3D;
  private readonly nodes: Record<ChainName, THREE.Object3D[]>;
  private readonly tips: Partial<Record<ChainName, THREE.Vector3>> = {};
  private readonly surface: Partial<Record<ChainName, SkinPoint[][]>> = {};
  private readonly cache = new Map<string, HandPose>();
  private readonly positions = Array.from({ length: 4 }, () => new THREE.Vector3());
  private readonly rotations = Array.from({ length: 4 }, () => new THREE.Quaternion());
  private readonly local = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly basis = new THREE.Quaternion();
  private readonly mesh: THREE.SkinnedMesh;
  private readonly triangles: Uint32Array;
  private readonly wristIndex: number;
  private readonly boneIndices: Record<ChainName, number[]>;
  private readonly palm = new THREE.Box3();
  private readonly palette: THREE.Matrix4[];
  private readonly skinned: THREE.Vector3[];
  private readonly boneChains = new Map<number, ChainName>();
  private readonly blockedChains = new Set<ChainName>();
  private readonly sourceTwists: Partial<Record<ChainName, number>> = {};
  private readonly guitar: AuthoredGuitarSurface | null;
  private readonly vertexChains: (ChainName | null)[];
  private readonly bindings: SkinBinding[];
  private readonly allVertices: number[];
  private readonly chainVertices: Record<ChainName, number[]>;
  private readonly thumbWeights: number[];
  private readonly thumbPad: number[];
  private readonly thumbFaces: number[] = [];
  private readonly depths: Float64Array;
  private readonly sample = new THREE.Vector3();
  private readonly supportSpan = new THREE.Vector2();
  private intersectingFaces: number[] = [];

  constructor(private readonly root: THREE.Group, private readonly info: AuthoredSceneInfo, side: 'Left' | 'Right' = 'Left',
    private readonly prepared?: AuthoredHandPoses, private readonly sourceBases: readonly THREE.Quaternion[] = []) {
    const required = (name: string): THREE.Object3D => {
      const node = root.getObjectByName(name);
      if (!node) throw new Error(`Original fretting rig is missing ${name}`);
      return node;
    };
    this.wrist = required(`${side}Hand`);
    this.pivot = required(side === 'Left' ? 'SolElParent' : 'SaglElParent');
    this.basis.setFromRotationMatrix(new THREE.Matrix4().extractRotation(stageMatrix(root, this.wrist)));
    const scale = new THREE.Vector3().setFromMatrixScale(stageMatrix(root, this.wrist));
    if (Math.max(scale.x, scale.y, scale.z) - Math.min(scale.x, scale.y, scale.z) > .001) throw new Error('Original hand scale is not uniform');
    this.scale = scale.x;
    const primitives: THREE.SkinnedMesh[] = [];
    required(`APK_${side}`).traverse(node => { if (node instanceof THREE.SkinnedMesh) primitives.push(node); });
    const mesh = primitives[0];
    if (!mesh) throw new Error('Original fretting hand has no skin');
    const skeleton = mesh.skeleton;
    const wristIndex = skeleton.bones.findIndex(bone => bone === this.wrist);
    if (wristIndex < 0) throw new Error('Original wrist has no skin binding');
    this.mesh = mesh;
    this.triangles = Uint32Array.from(primitives.flatMap(primitive => {
      if (!primitive.geometry.index || primitive.geometry.getAttribute('position').array !== mesh.geometry.getAttribute('position').array) {
        throw new Error('Original hand skin primitives do not share indexed vertices');
      }
      return Array.from(primitive.geometry.index.array);
    }));
    this.wristIndex = wristIndex;
    this.palette = skeleton.bones.map(() => new THREE.Matrix4());
    this.skinned = Array.from({ length: mesh.geometry.getAttribute('position').count }, () => new THREE.Vector3());
    this.nodes = Object.fromEntries(CHAIN_NAMES.map(name => [name,
      [1, 2, 3].map(i => required(`${side}Hand${name[0].toUpperCase()}${name.slice(1)}${i}`)),
    ])) as Record<ChainName, THREE.Object3D[]>;
    this.boneIndices = Object.fromEntries(CHAIN_NAMES.map(name => [name,
      this.nodes[name].map(node => skeleton.bones.findIndex(bone => bone === node)),
    ])) as Record<ChainName, number[]>;
    for (const name of CHAIN_NAMES) for (const bone of this.boneIndices[name]) this.boneChains.set(bone, name);
    const skinPositions = mesh.geometry.getAttribute('position'), skinIndices = mesh.geometry.getAttribute('skinIndex');
    const skinWeights = mesh.geometry.getAttribute('skinWeight');
    this.bindings = Array.from({ length: skinPositions.count }, (_, v) => ({
      point: new THREE.Vector3().fromBufferAttribute(skinPositions, v).applyMatrix4(mesh.bindMatrix),
      influences: [0, 1, 2, 3].flatMap(k => skinWeights.getComponent(v, k)
        ? [{ bone: skinIndices.getComponent(v, k), weight: skinWeights.getComponent(v, k) }] : []),
    }));
    this.allVertices = this.bindings.map((_, v) => v);
    this.depths = new Float64Array(this.bindings.length);
    this.chainVertices = Object.fromEntries(CHAIN_NAMES.map(name => [name,
      this.allVertices.filter(v => this.bindings[v].influences.some(part => this.boneChains.get(part.bone) === name)),
    ])) as Record<ChainName, number[]>;
    this.thumbWeights = this.bindings.map(binding => binding.influences.reduce((sum, part) =>
      sum + (this.boneChains.get(part.bone) === 'thumb' ? part.weight : 0), 0));
    this.thumbPad = this.chainVertices.thumb.filter(v => this.bindings[v].influences
      .some(part => part.bone === this.boneIndices.thumb[2] && part.weight >= .7));
    if (!this.thumbPad.length) throw new Error('The original thumb has no measurable supporting pad');
    for (let i = 0; i < this.triangles.length; i += 3) {
      if (this.thumbWeights[this.triangles[i]] || this.thumbWeights[this.triangles[i + 1]] || this.thumbWeights[this.triangles[i + 2]]) this.thumbFaces.push(i);
    }
    this.vertexChains = Array.from({ length: skinPositions.count }, (_, v) => {
      let weight = 0, chain: ChainName | null = null;
      for (let k = 0; k < 4; k++) if (skinWeights.getComponent(v, k) > weight) {
        weight = skinWeights.getComponent(v, k);
        chain = this.boneChains.get(skinIndices.getComponent(v, k)) ?? null;
      }
      return this.thumbWeights[v] >= .5 ? 'thumb' : chain;
    });
    this.guitar = side === 'Left' ? new AuthoredGuitarSurface(root) : null;
    for (let v = 0; v < skinPositions.count; v++) for (let k = 0; k < 4; k++) {
      if (skinIndices.getComponent(v, k) === wristIndex && skinWeights.getComponent(v, k) > .99) {
        this.palm.expandByPoint(new THREE.Vector3().fromBufferAttribute(skinPositions, v).applyMatrix4(skeleton.boneInverses[wristIndex]));
      }
    }
    if (this.palm.isEmpty()) throw new Error('Original palm could not be measured');
    const restPosition = [new THREE.Vector3()], restQuaternion = [new THREE.Quaternion()];
    const chains: Partial<HandKinematics['chains']> = {};
    for (const name of CHAIN_NAMES) {
      const nodes = this.nodes[name];
      if (!(nodes[2] instanceof THREE.Bone)) throw new Error('Original finger joint is not a bone');
      const distal = skeleton.bones.indexOf(nodes[2]);
      if (distal < 0) throw new Error('Original distal joint has no skin binding');
      const vertices = mesh.geometry.getAttribute('position'), indices = mesh.geometry.getAttribute('skinIndex');
      const weights = mesh.geometry.getAttribute('skinWeight');
      const tip = new THREE.Vector3(0, 0, -Infinity), vertex = new THREE.Vector3();
      const boneIndices = nodes.map(node => skeleton.bones.findIndex(bone => bone === node));
      const surface: SkinPoint[][] = [];
      for (let v = 0; v < vertices.count; v++) {
        let weight = 0;
        for (let k = 0; k < 4; k++) if (indices.getComponent(v, k) === distal) weight += weights.getComponent(v, k);
        if (weight >= .7) {
          vertex.fromBufferAttribute(vertices, v).applyMatrix4(skeleton.boneInverses[distal]);
          if (vertex.z > tip.z) tip.copy(vertex);
        }
        const point: SkinPoint[] = [];
        let total = 0;
        for (let k = 0; k < 4; k++) {
          const bone = indices.getComponent(v, k), joint = boneIndices.indexOf(bone), weight = weights.getComponent(v, k);
          if (joint < 0 || !weight) continue;
          point.push({ joint, weight, local: new THREE.Vector3().fromBufferAttribute(vertices, v).applyMatrix4(skeleton.boneInverses[bone]) });
          total += weight;
        }
        if (total > .999) surface.push(point);
      }
      if (!Number.isFinite(tip.z) || tip.z < .01 || tip.z > .05) throw new Error('Original fingertip could not be measured');
      this.tips[name] = tip.clone();
      this.surface[name] = surface;
      const start = restPosition.length;
      const joints: [number, number, number, number] = [start, start + 1, start + 2, start + 3];
      const contact = tip.clone().applyQuaternion(AXES);
      const relP = [nodes[0].position.clone(), nodes[1].position.clone().applyQuaternion(AXES),
        nodes[2].position.clone().applyQuaternion(AXES), contact.clone()];
      const bind = skeleton.boneInverses[wristIndex].clone().multiply(skeleton.boneInverses[boneIndices[0]].clone().invert());
      const neutral = new THREE.Quaternion().setFromRotationMatrix(bind);
      const angles = new THREE.Euler().setFromQuaternion(neutral, 'YXZ');
      if (name !== 'thumb') angles.x = 0;
      const relQ = [neutral.setFromEuler(angles).multiply(AXES),
        new THREE.Quaternion(), new THREE.Quaternion(), new THREE.Quaternion()];
      const source = relQ[0].clone().invert().multiply(nodes[0].quaternion).multiply(AXES);
      this.sourceTwists[name] = new THREE.Euler().setFromQuaternion(source, 'YXZ').z;
      let p = new THREE.Vector3(), q = new THREE.Quaternion();
      for (let k = 0; k < 4; k++) {
        p = relP[k].clone().applyQuaternion(q).add(p); q = q.clone().multiply(relQ[k]);
        restPosition.push(p); restQuaternion.push(q);
      }
      const limits: [number, number][] = (name === 'thumb' ? THUMB_LIMITS : FINGER_LIMITS).map(([min, max]) => [min, max]);
      const twist = name === 'thumb' ? THUMB_TWIST : FINGER_TWIST;
      limits.push([...twist]);
      chains[name] = {
        parent: 0, joints, relP, relQ, contact, coupling: name === 'thumb' ? .6 : .7,
        limits,
      };
    }
    this.hand = { restPosition, restQuaternion, chains: chains as HandKinematics['chains'], spreadSign: 1 };
  }

  targets(frets: Frets): AuthoredFingerTarget[] {
    if (frets.length !== 6 || frets.some(fret => fret !== null && (!Number.isInteger(fret) || fret < 0 || fret >= this.info.layout.frets.length))) {
      throw new Error('Original hands need six valid fret positions');
    }
    const fingering = suggestFingering(frets);
    return ([1, 2, 3, 4] as const).flatMap(finger => {
      const strings = frets.flatMap((fret, s) => fret !== null && fret > 0 && fingering.fingers[s] === finger ? [s] : []);
      if (!strings.length) return [];
      const fret = frets[strings[0]]!, chain = FINGER_CHAIN[finger];
      const left = this.info.layout.frets[fret - 1], right = this.info.layout.frets[fret];
      const start = left + (right - left) * .3, end = right - Math.min(.18, (right - left) * .2);
      const string = strings[strings.length - 1];
      const point = authoredStringPoint(this.info, string, start), far = authoredStringPoint(this.info, string, end);
      if (strings.length > 1) {
        const next = frets[string + 1];
        const padding = next !== undefined && next !== null && next < fret ? .04 : .12;
        point.z += padding; far.z += padding;
      }
      const span = strings[strings.length - 1] - strings[0];
      const flat = strings.length > 1 ? span >= 3 ? 0 : span === 2 ? .22 : .6 : undefined;
      const startPose: ChainPose = flat === undefined ? [0, .75, 1.3] : [0, .8, flat];
      startPose.twist = this.sourceTwists[chain]!;
      return [{ chain, fret, strings, target: { chain, point, end: far, flat, distal: flat === undefined ? undefined : 0,
        start: startPose } }];
    });
  }

  solve(frets: Frets): HandPose {
    const key = frets.map(fret => fret === null ? 'x' : fret).join('.');
    const cached = this.cache.get(key);
    if (cached) return cached;
    const packed = this.prepared?.poses[key];
    if (packed) {
      const pose = this.unpack(packed);
      if (this.cache.size >= 512) this.cache.delete(this.cache.keys().next().value!);
      this.cache.set(key, pose);
      return pose;
    }
    const pose = this.solveUnprepared(frets);
    if (this.cache.size >= 512) this.cache.delete(this.cache.keys().next().value!);
    this.cache.set(key, pose);
    return pose;
  }

  private solveUnprepared(frets: Frets): HandPose {
    const targets = this.targets(frets);
    const base = this.basis;
    const thumbX = targets.length ? targets.reduce((x, t) => x + t.target.point.x, 0) / targets.length : -3.5;
    const thumbStart: ChainPose = [0, .3, .65]; thumbStart.twist = this.sourceTwists.thumb!;
    thumbStart.distal = .65 * this.hand.chains.thumb.coupling;
    const thumb: ChainTarget = {
      chain: 'thumb', point: new THREE.Vector3(thumbX, this.thumbBackHeight(thumbX) - .15, -.15),
      start: thumbStart, weight: 1, independentJoints: true,
    };
    const request: PlacementRequest = {
      scale: this.scale, base, anchor: 'middle', xs: [0], ys: [.35, .85, 1.3], zs: [-1.7, -2.3, -2.9],
      rolls: [-.25, 0, .25], rollAxis: X, yaws: [-.25, 0, .25], yawAxis: Z,
      defaultX: this.info.layout.frets[2], targets: [...targets.map(target => target.target), thumb], accuracyWeight: 200, forearm: new THREE.Vector3(.5, -1, -.5),
      penalty: (name, joints, flat) => {
        let cost = 0;
        if (name === 'thumb') {
          for (const p of joints) cost += Math.max(0, p.y - this.thumbBackHeight(p.x) + .3) ** 2 * 80;
          return cost;
        }
        for (let k = 0; k < 3; k++) {
          const p = joints[k];
          if (Math.abs(p.z) < 1.3) cost += Math.max(0, (flat ? .45 : .65) - p.y) ** 2 * 50;
        }
        if (!flat) {
          const approach = joints[3].clone().sub(joints[2]).normalize();
          cost += Math.max(0, approach.y + .95) ** 2 * 80;
        }
        if (flat) {
          const target = targets.find(target => target.chain === name)!;
          for (const string of target.strings) {
            cost += padDistance(joints, authoredStringPoint(this.info, string, target.target.point.x),
              authoredStringPoint(this.info, string, target.target.end!.x), this.scale) ** 2 * 100;
          }
        }
        return cost;
      },
      rest: name => name === 'thumb' ? thumb : [0, .85, 1.4],
    };
    const finish = (candidate: ReturnType<typeof placeHand>, refine = false) => {
      for (const name of CHAIN_NAMES) {
        candidate.pose.chains[name].distal ??= candidate.pose.chains[name][2] * this.hand.chains[name].coupling;
        candidate.pose.chains[name].twist ??= 0;
      }
      for (const target of targets) this.refineContact(candidate.pose, target);
      this.restThumb(candidate.pose, targets);
      let clearance = this.clearanceError(candidate.pose, frets);
      if (clearance) for (const name of CHAIN_NAMES) {
        if (name === 'thumb' || targets.some(target => target.chain === name)) continue;
        let selected = candidate.pose.chains[name];
        for (const [mcp, pip] of [[.45, .8], [.65, 1.1], [1.1, 1.7], [1.5, 1.8]]) {
          const rest: ChainPose = [0, mcp, pip]; rest.distal = pip * this.hand.chains[name].coupling; rest.twist = this.sourceTwists[name]!;
          candidate.pose.chains[name] = rest;
          const distance = this.clearanceError(candidate.pose, frets);
          if (distance < clearance) { selected = rest; clearance = distance; }
          if (!clearance) break;
        }
        candidate.pose.chains[name] = selected;
        if (!clearance) break;
      }
      if (refine && (clearance || this.placementError(candidate.pose, targets) > .08)) this.refineClearance(candidate.pose, targets, frets);
      return Math.hypot(this.placementError(candidate.pose, targets), refine ? this.clearanceError(candidate.pose, frets) : clearance);
    };
    let selectedRequest = request;
    let result = placeHand(this.hand, request);
    let error = finish(result, true);
    if (error > .08) {
      const neutral: PlacementRequest = { ...request, targets: request.targets.map(target => {
        if (!target.start) return target;
        const start: ChainPose = [target.start[0], target.start[1], target.start[2]];
        if (target.start.distal !== undefined) start.distal = target.start.distal;
        start.twist = 0;
        return { ...target, start };
      }) };
      const candidate = placeHand(this.hand, neutral), distance = finish(candidate, true);
      if (distance < error) { result = candidate; error = distance; selectedRequest = neutral; }
    }
    const alternatives = [...this.sourceBases,
      ...[0, .5, -.5, .9, -.9, 1.2, -1.2].map(turn => new THREE.Quaternion().setFromAxisAngle(Y, turn).multiply(base))];
    alternatives.push(basisRotation(X, new THREE.Vector3(0, .8, .6), Y.clone().negate(), new THREE.Vector3(0, -.6, .8)));
    if (error > .08) for (const avoidPalm of [false, true]) {
      for (const orientation of alternatives) {
        const attempt: PlacementRequest = { ...request, base: orientation,
          palmPenalty: avoidPalm ? (position, quaternion) => this.palmPenalty(position, quaternion, frets) : undefined };
        const candidate = placeHand(this.hand, attempt);
        const distance = finish(candidate);
        if (distance < error) { result = candidate; error = distance; selectedRequest = attempt; }
        if (error < .07) break;
      }
      if (error < .07) break;
    }
    if (error > .12) for (const target of targets.filter(target => target.target.flat !== undefined)) {
      const current = selectedRequest;
      for (const flat of [.15, .4, .9, 1.25, 1.6]) {
        const attempt = { ...current, targets: current.targets.map(item => item.chain === target.chain ? { ...item, flat } : item) };
        const candidate = placeHand(this.hand, attempt), distance = finish(candidate);
        if (distance < error) { result = candidate; error = distance; selectedRequest = attempt; }
      }
    }
    if (error > .08) {
      const before = clonePose(result.pose);
      if (finish(result, true) > error) result.pose = before;
    }
    return result.pose;
  }

  private thumbBackHeight(x: number): number {
    return this.guitar?.backHeight(THREE.MathUtils.clamp(x, this.info.layout.frets[0], this.info.layout.frets.at(-1)!)) ?? 0;
  }

  private thumbBackIntrusion(point: THREE.Vector3, margin = 0): number {
    if (!this.guitar) return 0;
    // A thumb outside the neck's silhouette must not escape the rear-side constraint.
    return Math.max(0, point.y - this.thumbBackHeight(point.x) + margin, this.guitar.backIntrusion(point, margin));
  }

  private supportDistance(targets: readonly AuthoredFingerTarget[]): number {
    if (!this.guitar) return 0;
    const from = targets.length ? Math.min(...targets.map(target => target.target.point.x)) : this.info.layout.frets[2] - .4;
    const to = targets.length ? Math.max(...targets.map(target => target.target.end!.x)) : this.info.layout.frets[2] + .4;
    let distance = Infinity;
    for (const v of this.thumbPad) {
      const p = this.skinned[v], x = THREE.MathUtils.clamp(p.x, from - .7, to + .7), z = THREE.MathUtils.clamp(p.z, -.6, .6);
      if (!this.guitar.verticalSpan(x, z, this.supportSpan)) continue;
      distance = Math.min(distance, Math.hypot(p.x - x, p.y - this.supportSpan.x, p.z - z));
    }
    return distance;
  }

  thumbSupportDistance(pose: HandPose, targets: readonly AuthoredFingerTarget[]): number {
    this.skinPose(pose, 'thumb');
    return this.supportDistance(targets);
  }

  private restThumb(pose: HandPose, targets: readonly AuthoredFingerTarget[]): void {
    if (!this.guitar) return;
    this.skinPose(pose);
    const measure = () => {
      let solid = this.poseSolidError(pose, 'thumb'), depth = 0;
      for (const face of this.thumbFaces) depth = Math.max(depth, this.surfaceDepth(face));
      if (depth > 1e-6) solid = Math.max(solid, .2 + depth);
      const distance = this.supportDistance(targets);
      return { solid, distance, cost: solid * solid * 40 + distance * distance };
    };
    let best = measure(), selected = clonePose(pose).chains.thumb;
    if (!best.solid && best.distance <= AUTHORED_THUMB_SUPPORT_LIMIT - .005) return;
    const x = targets.length ? targets.reduce((sum, target) => sum + target.target.point.x, 0) / targets.length : this.info.layout.frets[2];
    const target = new THREE.Vector3(x, this.thumbBackHeight(x) - .15, -.15), point = new THREE.Vector3();
    const candidates: { chain: ChainPose; cost: number }[] = [];
    for (const spread of [-.8, 0, .8]) for (const mcp of [-.5, 0, .6, 1.2]) for (const pip of [0, .7, 1.35]) {
      for (const distal of [0, .7, 1.35]) for (const twist of [-1.1, 0, 1.1]) {
        const chain: ChainPose = [spread, mcp, pip]; chain.distal = distal; chain.twist = twist;
        chainFK(this.hand, 'thumb', chain, this.positions, this.rotations);
        let depth = 0;
        for (let i = 0; i < 4; i++) {
          point.copy(toStage(this.positions[i], pose.position, pose.quaternion, this.scale));
          depth += Math.max(0, point.y - this.thumbBackHeight(point.x) + (i === 3 ? .04 : .3)) ** 2;
        }
        candidates.push({ chain, cost: point.distanceToSquared(target) + depth * 40 });
      }
    }
    candidates.sort((a, b) => a.cost - b.cost);
    const seeds = candidates.slice(0, 64).map(candidate => {
      pose.chains.thumb = candidate.chain;
      return { chain: candidate.chain, score: measure() };
    }).sort((a, b) => a.score.cost - b.score.cost).slice(0, 12);
    for (const seed of seeds) {
      pose.chains.thumb = seed.chain;
      let score = seed.score, step = .25;
      for (let round = 0; round < 100 && step > .002; round++) {
        if (!score.solid && score.distance < .08) break;
        let improved = false;
        for (const joint of [0, 1, 2, 3, 4] as const) {
          const chain = pose.chains.thumb, initial = joint === 4 ? chain.twist! : joint === 3 ? chain.distal! : chain[joint];
          let choice = initial;
          for (const sign of [-1, 1]) {
            const value = THREE.MathUtils.clamp(initial + sign * step, ...this.hand.chains.thumb.limits[joint]);
            if (joint === 4) chain.twist = value; else if (joint === 3) chain.distal = value; else chain[joint] = value;
            const other = measure();
            if (other.cost < score.cost - 1e-9) { score = other; choice = value; improved = true; }
          }
          if (joint === 4) chain.twist = choice; else if (joint === 3) chain.distal = choice; else chain[joint] = choice;
        }
        if (!improved) step *= .5;
      }
      const current = measure();
      if (current.cost < best.cost) { best = current; selected = clonePose(pose).chains.thumb; }
      if (!best.solid && best.distance < .08) break;
    }
    pose.chains.thumb = selected;
  }

  /** Preparation-only repair; normal playback continues to use immutable, prevalidated poses. */
  repair(frets: Frets): HandPose {
    const pose = clonePose(this.solve(frets)), targets = this.targets(frets);
    const key = frets.map(fret => fret === null ? 'x' : fret).join('.');
    this.restThumb(pose, targets);
    let error = this.poseSolidError(pose);
    if (!error && this.thumbSupportDistance(pose, targets) <= AUTHORED_THUMB_SUPPORT_LIMIT) { this.cache.set(key, pose); return pose; }
    const blocked = new Set(this.blockedChains);
    for (const name of CHAIN_NAMES) {
      if (!blocked.has(name) || targets.some(target => target.chain === name)) continue;
      const initial = pose.chains[name];
      let selected = initial, best = error, change = 0;
      const mcps = name === 'thumb' ? [-.7, -.4, 0, .4, .8, 1.2] : [-.2, 0, .25, .45, .65, .85, 1.1, 1.3, 1.5];
      const pips = name === 'thumb' ? [0, .4, .8, 1.2] : [0, .4, .8, 1.1, 1.4, 1.7];
      for (const mcp of mcps) for (const pip of pips) {
        const chain: ChainPose = [initial[0], mcp, pip];
        chain.distal = pip * this.hand.chains[name].coupling; chain.twist = initial.twist;
        pose.chains[name] = chain;
        const distance = this.poseSolidError(pose);
        const movement = (mcp - initial[1]) ** 2 + (pip - initial[2]) ** 2 + (chain.distal - initial.distal!) ** 2;
        if (distance < best - 1e-6 || (Math.abs(distance - best) < 1e-6 && movement < change)) {
          selected = chain; best = distance; change = movement;
        }
      }
      pose.chains[name] = selected; error = best;
    }
    if (error) this.refineClearance(pose, targets, frets, true);
    if (this.clearanceError(pose, frets)) this.refineClearance(pose, targets, frets);
    this.cache.set(key, pose);
    return pose;
  }

  constrainTransition(pose: HandPose, previous: HandPose): HandPose {
    const projected = clonePose(pose);
    if (this.projectClearance(projected, [], [null, null, null, null, null, null], 12)) return projected;
    if (!this.motionClear(previous)) throw new Error('The previous hand pose does not clear the guitar');
    // A bounded collision constraint must never publish an intersecting intermediate frame.
    let low = 0, high = 1, safe = previous;
    const candidate = clonePose(previous);
    for (let i = 0; i < 6; i++) {
      const t = (low + high) / 2;
      blendPose(previous, pose, t, candidate);
      if (!this.motionClear(candidate)) high = t;
      else { low = t; safe = clonePose(candidate); }
    }
    return safe;
  }

  private projectClearance(pose: HandPose, targets: readonly AuthoredFingerTarget[], frets: Frets, rounds: number): boolean {
    if (this.motionClear(pose)) return true;
    // Refine only the worst current contacts, then recheck the complete skin.
    const support = new Set<number>(), faces = new Set<number>();
    let step = .06;
    for (let round = 0; round < rounds && step > .0005; round++) {
      const worst = new Map<number, number>();
      for (const v of this.allVertices) {
        if (this.depths[v] < 1e-6) continue;
        const bone = this.bindings[v].influences.reduce((largest, part) => part.weight > largest.weight ? part : largest).bone;
        const current = worst.get(bone);
        if (current === undefined || this.depths[v] > this.depths[current]) worst.set(bone, v);
      }
      if (!worst.size && !this.intersectingFaces.length) break;
      for (const v of worst.values()) support.add(v);
      for (const face of this.intersectingFaces) faces.add(face);
      const vertices = [...support], triangles = [...faces];
      const skin = [...new Set([...vertices, ...triangles.flatMap(i => [...this.triangles.subarray(i, i + 3)])])];
      step = this.refineClearance(pose, targets, frets, true, 2, { vertices, faces: triangles, skin }, step);
      if (this.motionClear(pose)) return true;
    }
    return false;
  }

  private motionClear(pose: HandPose): boolean {
    this.intersectingFaces = [];
    if (this.poseSolidError(pose)) return false;
    const worst = new Map<ChainName | null, { face: number; depth: number }>();
    for (let i = 0; i < this.triangles.length; i += 3) {
      const depth = this.surfaceDepth(i);
      if (depth < 1e-6) continue;
      const chain = this.vertexChains[this.triangles[i]], current = worst.get(chain);
      if (!current || current.depth < depth) worst.set(chain, { face: i, depth });
    }
    this.intersectingFaces = [...worst.values()].map(item => item.face);
    return !worst.size;
  }

  private surfaceDepth(i: number): number {
    const a = this.skinned[this.triangles[i]], b = this.skinned[this.triangles[i + 1]], c = this.skinned[this.triangles[i + 2]];
    const weight = this.thumbWeights[this.triangles[i]] + this.thumbWeights[this.triangles[i + 1]] + this.thumbWeights[this.triangles[i + 2]];
    let depth = this.surfacePointDepth(this.sample.copy(a).add(b).add(c).divideScalar(3), weight >= 1.5);
    for (let k = 0; k < 3; k++) {
      this.sample.copy(this.skinned[this.triangles[i + k]]).lerp(this.skinned[this.triangles[i + (k + 1) % 3]], .5);
      const edgeWeight = this.thumbWeights[this.triangles[i + k]] + this.thumbWeights[this.triangles[i + (k + 1) % 3]];
      depth = Math.max(depth, this.surfacePointDepth(this.sample, edgeWeight >= 1));
    }
    return depth;
  }

  private surfacePointDepth(point: THREE.Vector3, thumb: boolean): number {
    return thumb ? this.thumbBackIntrusion(point, .004) : this.guitar?.penetration(point, .004) ?? 0;
  }

  private palmPenalty(position: THREE.Vector3, quaternion: THREE.Quaternion, frets: Frets): number {
    const inverse = quaternion.clone().invert(), start = new THREE.Vector3(), end = new THREE.Vector3();
    const entry = new THREE.Vector3(), exit = new THREE.Vector3(), ray = new THREE.Ray();
    let cost = 0;
    for (let s = 0; s < 6; s++) {
      if (frets[s] === null) continue;
      start.copy(authoredStringPoint(this.info, s, this.info.layout.frets[frets[s]!] + .001)).sub(position).applyQuaternion(inverse).divideScalar(this.scale);
      end.fromArray(this.info.layout.strings[s].saddle).sub(position).applyQuaternion(inverse).divideScalar(this.scale);
      ray.set(start, end.clone().sub(start).normalize());
      if (this.palm.containsPoint(start)) entry.copy(start);
      else if (!ray.intersectBox(this.palm, entry) || entry.distanceToSquared(start) > end.distanceToSquared(start)) continue;
      ray.set(end, start.clone().sub(end).normalize());
      if (this.palm.containsPoint(end)) exit.copy(end);
      else if (!ray.intersectBox(this.palm, exit)) continue;
      entry.lerp(exit, .5);
      const depth = Math.min(entry.x - this.palm.min.x, this.palm.max.x - entry.x,
        entry.y - this.palm.min.y, this.palm.max.y - entry.y, entry.z - this.palm.min.z, this.palm.max.z - entry.z) * this.scale;
      cost += (depth + .02) ** 2 * 200;
    }
    return cost;
  }

  private evaluatedVertices(selected?: ChainName, vertices?: readonly number[]): readonly number[] {
    if (!vertices) return selected ? this.chainVertices[selected] : this.allVertices;
    return selected ? vertices.filter(v => this.bindings[v].influences.some(part => this.boneChains.get(part.bone) === selected)) : vertices;
  }

  private skinPose(pose: HandPose, selected?: ChainName, vertices?: readonly number[]): void {
    const scale = new THREE.Vector3(this.scale, this.scale, this.scale);
    const inverses = this.mesh.skeleton.boneInverses;
    this.palette[this.wristIndex].compose(pose.position, pose.quaternion, scale).multiply(inverses[this.wristIndex]);
    for (const name of CHAIN_NAMES) {
      chainFK(this.hand, name, pose.chains[name], this.positions, this.rotations);
      for (let k = 0; k < 3; k++) {
        const bone = this.boneIndices[name][k];
        this.palette[bone].compose(toStage(this.positions[k], pose.position, pose.quaternion, this.scale),
          pose.quaternion.clone().multiply(this.rotations[k]).multiply(AXES), scale).multiply(inverses[bone]);
      }
    }
    const part = new THREE.Vector3();
    for (const v of this.evaluatedVertices(selected, vertices)) {
      this.skinned[v].set(0, 0, 0);
      for (const { bone, weight } of this.bindings[v].influences) {
        this.skinned[v].addScaledVector(part.copy(this.bindings[v].point).applyMatrix4(this.palette[bone]), weight);
      }
    }
  }

  private poseSolidError(pose: HandPose, selected?: ChainName, samples?: CollisionSamples): number {
    this.blockedChains.clear();
    this.skinPose(pose, selected, samples?.skin);
    return this.solidError(selected, samples);
  }

  solidPenetration(pose: HandPose): number {
    this.skinPose(pose);
    return this.skinned.reduce((maximum, point) => Math.max(maximum, this.guitar?.penetration(point) ?? 0), 0);
  }

  private solidError(selected?: ChainName, samples?: CollisionSamples): number {
    if (!this.guitar) return 0;
    let maximum = 0, sum = 0;
    for (const v of this.evaluatedVertices(selected, samples?.vertices)) {
      const chain = this.vertexChains[v];
      const depth = chain === 'thumb' ? this.thumbBackIntrusion(this.skinned[v], .004)
        : chain ? this.guitar.frontIntrusion(this.skinned[v], .004) : this.guitar.penetration(this.skinned[v], .004);
      this.depths[v] = depth;
      if (depth < 1e-6) continue;
      maximum = Math.max(maximum, depth); sum += depth * depth;
      if (chain) this.blockedChains.add(chain);
    }
    for (const face of samples?.faces ?? []) {
      const depth = this.surfaceDepth(face);
      if (depth < 1e-6) continue;
      maximum = Math.max(maximum, depth); sum += depth * depth;
      for (let k = 0; k < 3; k++) {
        const chain = this.vertexChains[this.triangles[face + k]];
        if (chain) this.blockedChains.add(chain);
      }
    }
    return maximum ? .2 + maximum + 8 * Math.sqrt(sum / this.skinned.length) : 0;
  }

  private clearanceError(pose: HandPose, frets: Frets): number {
    this.blockedChains.clear();
    this.skinPose(pose);
    const solid = this.solidError();
    const indices = this.mesh.geometry.getAttribute('skinIndex'), weights = this.mesh.geometry.getAttribute('skinWeight');
    const triangles = this.triangles, point = new THREE.Vector3(), normal = new THREE.Vector3(), edge = new THREE.Vector3();
    let intersections = 0, overlap = 0;
    for (let s = 0; s < 6; s++) {
      if (frets[s] === null) continue;
      const start = authoredStringPoint(this.info, s, this.info.layout.frets[frets[s]!] + .001);
      const end = new THREE.Vector3(...this.info.layout.strings[s].saddle);
      const ray = new THREE.Ray(start, end.clone().sub(start).normalize()), hits: { x: number; crossing: number }[] = [];
      for (let i = 0; i < triangles.length; i += 3) {
        const a = this.skinned[triangles[i]], b = this.skinned[triangles[i + 1]], c = this.skinned[triangles[i + 2]];
        if (!ray.intersectTriangle(a, b, c, false, point)) continue;
        const crossing = Math.sign(normal.subVectors(b, a).cross(edge.subVectors(c, a)).dot(ray.direction));
        hits.push({ x: point.x, crossing });
        if (point.x > end.x) continue;
        for (let corner = 0; corner < 3; corner++) for (let k = 0; k < 4; k++) {
          const v = triangles[i + corner], name = this.boneChains.get(indices.getComponent(v, k));
          if (name && weights.getComponent(v, k) > .2) this.blockedChains.add(name);
        }
      }
      if (!hits.some(hit => hit.x <= end.x)) continue;
      intersections++;
      hits.sort((a, b) => a.x - b.x);
      // A string can start inside overlapping fingers. Pairing exits cancels their occupied spans.
      let winding = hits.reduce((sum, hit) => sum + hit.crossing, 0), previous = start.x;
      for (const hit of hits) {
        const x = Math.min(hit.x, end.x);
        if (winding) overlap += x - previous;
        winding -= hit.crossing; previous = x;
        if (hit.x >= end.x) break;
      }
    }
    const support = Math.max(0, this.supportDistance(this.targets(frets)) - AUTHORED_THUMB_SUPPORT_LIMIT);
    if (support) this.blockedChains.add('thumb');
    // Do not trap refinement by ranking two shallow contacts above one deep intersection.
    return Math.hypot(solid, intersections ? .2 + .2 * Math.sqrt(overlap) : 0, support ? .2 + support : 0);
  }

  private refineClearance(pose: HandPose, targets: readonly AuthoredFingerTarget[], frets: Frets, solidOnly = false, rounds = 42,
    samples?: CollisionSamples, step = .06): number {
    const measure = (selected?: ChainName) => solidOnly ? this.poseSolidError(pose, selected, samples) : this.clearanceError(pose, frets);
    let clearance = measure();
    let error = Math.hypot(this.placementError(pose, targets), clearance);
    const anchor = new THREE.Vector3();
    if (targets.length) {
      for (const target of targets) anchor.add(target.target.point);
      anchor.divideScalar(targets.length);
    } else anchor.copy(pose.position);
    for (let round = 0; round < rounds && error > .07 && step > (samples ? .0005 : .002); round++) {
      const names = [...new Set([...this.blockedChains,
        ...targets.filter(target => this.placementError(pose, [target]) > .07).map(target => target.chain)])];
      if (!names.length && !clearance) break;
      let improved = false;
      for (const name of names) {
        if (solidOnly) error = Math.hypot(this.placementError(pose, targets), measure(name));
        for (const joint of [0, 1, 2, 3, 4] as const) {
          const chain = pose.chains[name], limits = this.hand.chains[name].limits;
          const initial = joint === 4 ? chain.twist ?? 0 : joint === 3 ? chain.distal! : chain[joint];
          let selected = initial;
          for (const sign of [-1, 1]) {
            const value = THREE.MathUtils.clamp(initial + sign * step, limits[joint][0], limits[joint][1]);
            if (joint === 4) chain.twist = value; else if (joint === 3) chain.distal = value; else chain[joint] = value;
            const distance = Math.hypot(this.placementError(pose, targets), measure(name));
            if (distance < error - .000001) { selected = value; error = distance; improved = true; }
          }
          if (joint === 4) chain.twist = selected; else if (joint === 3) chain.distal = selected; else chain[joint] = selected;
        }
        if (solidOnly) measure(name);
      }
      if (solidOnly) error = Math.hypot(this.placementError(pose, targets), measure());
      if (!improved) for (const axis of [X, Y, Z]) for (const rotate of [true, false]) {
        const position = pose.position.clone(), quaternion = pose.quaternion.clone();
        let selectedPosition = position, selectedQuaternion = quaternion;
        for (const sign of [-1, 1]) {
          pose.position.copy(position); pose.quaternion.copy(quaternion);
          if (rotate) {
            const turn = new THREE.Quaternion().setFromAxisAngle(axis, sign * step / 2);
            pose.position.sub(anchor).applyQuaternion(turn).add(anchor);
            pose.quaternion.premultiply(turn).normalize();
          } else pose.position.addScaledVector(axis, sign * step / 2);
          const distance = Math.hypot(this.placementError(pose, targets), measure());
          if (distance < error - .000001) {
            selectedPosition = pose.position.clone(); selectedQuaternion = pose.quaternion.clone(); error = distance; improved = true;
          }
        }
        pose.position.copy(selectedPosition); pose.quaternion.copy(selectedQuaternion);
      }
      clearance = measure();
      if (!improved) step *= .5;
    }
    return step;
  }

  private unpack(data: readonly number[]): HandPose {
    const chains = Object.fromEntries(CHAIN_NAMES.map((name, i) => {
      const values = data.slice(7 + i * 5, 12 + i * 5), limits = this.hand.chains[name].limits;
      if (values.some((value, j) => value < limits[j][0] - 1e-7 || value > limits[j][1] + 1e-7)) {
        throw new Error('A prepared finger pose exceeds the native joint limits');
      }
      const chain: ChainPose = [values[0], values[1], values[2]]; chain.distal = values[3]; chain.twist = values[4];
      return [name, chain];
    })) as Record<ChainName, ChainPose>;
    return { position: new THREE.Vector3().fromArray(data), quaternion: new THREE.Quaternion().fromArray(data, 3).normalize(),
      chains, forearm: new THREE.Vector3(.5, -1, -.5).normalize() };
  }

  private refineContact(pose: HandPose, target: AuthoredFingerTarget): void {
    const chain = pose.chains[target.chain], limits = this.hand.chains[target.chain].limits;
    let error = this.placementError(pose, [target]), step = .05;
    if (error < .035) return;
    // Resolve the final pad contact on the real skin, including the independently extended distal joint.
    for (let round = 0; round < 28 && error > .025 && step > .003; round++) {
      let improved = false;
      for (const joint of [0, 1, 2, 3, 4] as const) {
        const initial = joint === 4 ? chain.twist ?? 0 : joint === 3 ? chain.distal! : chain[joint];
        let selected = initial;
        for (const sign of [-1, 1]) {
          const value = THREE.MathUtils.clamp(initial + sign * step, limits[joint][0], limits[joint][1]);
          if (joint === 4) chain.twist = value; else if (joint === 3) chain.distal = value; else chain[joint] = value;
          const distance = this.placementError(pose, [target]);
          if (distance < error - .00001) { selected = value; error = distance; improved = true; }
        }
        if (joint === 4) chain.twist = selected; else if (joint === 3) chain.distal = selected; else chain[joint] = selected;
      }
      if (!improved) step *= .5;
    }
  }

  surfaceError(pose: HandPose, targets: readonly AuthoredFingerTarget[]): number {
    return Math.max(0, ...this.contactDistances(pose, targets));
  }

  private contactDistances(pose: HandPose, targets: readonly AuthoredFingerTarget[]): number[] {
    const errors: number[] = [];
    const point = new THREE.Vector3(), value = new THREE.Vector3(), nearest = new THREE.Vector3();
    for (const target of targets) {
      chainFK(this.hand, target.chain, pose.chains[target.chain], this.positions, this.rotations);
      const positions = this.positions.map(p => toStage(p, pose.position, pose.quaternion, this.scale));
      const rotations = this.rotations.map(q => pose.quaternion.clone().multiply(q).multiply(AXES));
      const lines = target.strings.map(string => new THREE.Line3(
        authoredStringPoint(this.info, string, target.target.point.x), authoredStringPoint(this.info, string, target.target.end!.x)));
      if (target.strings.length === 1) {
        const tip = this.contact(pose, target.chain);
        errors.push(tip.distanceTo(lines[0].closestPointToPoint(tip, true, nearest)));
        continue;
      }
      const distances = lines.map(() => Infinity);
      for (const vertex of this.surface[target.chain]!) {
        point.set(0, 0, 0);
        for (const part of vertex) {
          value.copy(part.local).multiplyScalar(this.scale).applyQuaternion(rotations[part.joint]).add(positions[part.joint]);
          point.addScaledVector(value, part.weight);
        }
        for (let i = 0; i < lines.length; i++) distances[i] = Math.min(distances[i], point.distanceToSquared(lines[i].closestPointToPoint(point, true, nearest)));
      }
      errors.push(...distances.map(Math.sqrt));
    }
    return errors;
  }

  private placementError(pose: HandPose, targets: readonly AuthoredFingerTarget[]): number {
    const contacts = this.contactDistances(pose, targets), contact = Math.max(0, ...contacts);
    let approach = 0, totalApproach = 0;
    for (const target of targets) {
      if (target.strings.length !== 1) continue;
      chainFK(this.hand, target.chain, pose.chains[target.chain], this.positions, this.rotations);
      const direction = this.positions[3].clone().sub(this.positions[2]).applyQuaternion(pose.quaternion).normalize();
      const deficit = Math.max(0, direction.y + .9);
      approach = Math.max(approach, deficit); totalApproach += deficit;
    }
    // Max-only loss stalls when two fingers have equal errors: improving either appears to do nothing.
    return Math.hypot(contact, approach * .5) + Math.max(0, approach - .25) * 4 + Math.max(0, contact - .155) * 4
      + contacts.reduce((sum, error) => sum + error, 0) * .1 + totalApproach * .05;
  }

  apply(pose: HandPose): void {
    this.wrist.updateMatrix();
    this.local.copy(stageMatrix(this.root, this.pivot.parent!)).invert()
      .multiply(new THREE.Matrix4().compose(pose.position, pose.quaternion, new THREE.Vector3(this.scale, this.scale, this.scale)))
      .multiply(this.wrist.matrix.clone().invert());
    this.local.decompose(this.pivot.position, this.pivot.quaternion, this.pivot.scale);
    this.pivot.quaternion.normalize();
    for (const name of CHAIN_NAMES) {
      this.nodes[name].forEach((node, i) => {
        node.position.copy(this.hand.chains[name].relP[i]);
        if (i) node.position.applyQuaternion(AXES);
      });
      this.applyChain(name, pose.chains[name]);
    }
  }

  private applyChain(name: ChainName, pose: ChainPose): void {
    chainFK(this.hand, name, pose, this.positions, this.rotations);
    const parent = new THREE.Quaternion();
    for (let k = 0; k < 3; k++) {
      this.q.copy(this.rotations[k]).multiply(AXES);
      this.nodes[name][k].quaternion.copy(parent).invert().multiply(this.q).normalize();
      parent.copy(this.q);
    }
  }

  point(name: ChainName): THREE.Vector3 {
    return this.tips[name]!.clone().applyMatrix4(stageMatrix(this.root, this.nodes[name][2]));
  }

  /** Small joint corrections preserve the native pluck path while reaching a different string. */
  retarget(name: ChainName, target: THREE.Vector3): void {
    const chain = this.hand.chains[name], nodes = this.nodes[name];
    chain.relQ[0].copy(nodes[0].quaternion).multiply(AXES);
    for (let k = 1; k < 3; k++) chain.relQ[k].copy(AXES).multiply(nodes[k].quaternion).multiply(AXES);
    chain.limits = [[-.8, .8], [-.8, .8], [-.65, .65]];
    const local = target.clone().applyMatrix4(stageMatrix(this.root, this.wrist).invert());
    this.applyChain(name, solveChain(this.hand, name, local, [0, 0, 0], { iterations: 32 }).pose);
  }

  contact(pose: HandPose, name: ChainName): THREE.Vector3 {
    chainFK(this.hand, name, pose.chains[name], this.positions, this.rotations);
    const local = this.hand.chains[name].contact.clone().applyQuaternion(this.rotations[2]).add(this.positions[2]);
    return toStage(local, pose.position, pose.quaternion, this.scale);
  }
}
